<script setup lang="ts">
import {onMounted,ref} from 'vue';import {candidatesApi,type Candidate} from '@/lib/api';import CandidateCard from '@/components/domain/CandidateCard.vue';import {useToast} from '@/composables/useToast';const rows=ref<Candidate[]>([]);const {toast}=useToast();async function load(){rows.value=await candidatesApi.list({state:'discovered'})}onMounted(load);async function accept(id:number){try{const r=await candidatesApi.accept(id);toast(`已创建任务 #${r.task_id}`,'success');await load()}catch(e){toast(e instanceof Error?e.message:'采纳失败','error')}}async function ignore(id:number){await candidatesApi.ignore(id);toast('候选已忽略','info');await load()}
</script>
<template><div class="space-y-5"><div><h2 class="text-xl font-semibold">候选资源</h2><p class="text-sm text-muted">核对发现项后采纳转存，或忽略</p></div><div v-if="!rows.length" class="rounded-card border border-border p-6 text-muted">暂无待处理候选</div><div class="grid gap-3 lg:grid-cols-2"><CandidateCard v-for="candidate in rows" :key="candidate.id" :candidate="candidate" @accept="accept" @ignore="ignore"/></div></div></template>